# -*- coding: utf-8 -*-
SVGS = ['<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="26" text-anchor="middle" font-size="15" font-weight="bold" fill="#0f172a">EXPRESSING SUGGESTIONS &amp; SOLUTIONS (ÇÖZÜM ÖNERİSİ KALIPLARI)</text>\n  <rect x="25" y="45" width="310" height="195" rx="10" fill="#dbeafe" stroke="#2563eb" stroke-width="2"/>\n  <text x="180" y="68" text-anchor="middle" font-size="13" font-weight="bold" fill="#1e40af">Modal Verbs (Kip Belirteçleri)</text>\n  <text x="40" y="96" font-size="12" fill="#1e3a8a">• <tspan font-weight="bold">should / ought to + V1:</tspan> Tavsiye ve öneri</text>\n  <text x="50" y="114" font-size="11" fill="#1d4ed8">"We should respect everyone\'s dignity."</text>\n  <text x="40" y="140" font-size="12" fill="#1e3a8a">• <tspan font-weight="bold">must / need to + V1:</tspan> Güçlü gereklilik</text>\n  <text x="50" y="158" font-size="11" fill="#1d4ed8">"Laws must prevent discrimination."</text>\n  <text x="40" y="184" font-size="12" fill="#1e3a8a">• <tspan font-weight="bold">should be + V3 (Passive):</tspan> Edilgen öneri</text>\n  <text x="50" y="202" font-size="11" fill="#1d4ed8">"Equal rights should be guaranteed for all."</text>\n\n  <rect x="360" y="45" width="315" height="195" rx="10" fill="#dcfce7" stroke="#16a34a" stroke-width="2"/>\n  <text x="517" y="68" text-anchor="middle" font-size="13" font-weight="bold" fill="#166534">Formal Solution Expressions</text>\n  <text x="375" y="96" font-size="12" fill="#14532d">• <tspan font-weight="bold">It is vital / essential to + V1:</tspan></text>\n  <text x="385" y="114" font-size="11" fill="#15803d">"It is vital to support refugees and orphans."</text>\n  <text x="375" y="140" font-size="12" fill="#14532d">• <tspan font-weight="bold">Steps / Measures must be taken to + V1:</tspan></text>\n  <text x="385" y="158" font-size="11" fill="#15803d">"Strict measures must be taken to end poverty."</text>\n  <text x="375" y="184" font-size="12" fill="#14532d">• <tspan font-weight="bold">I suggest / recommend + V-ing / that...:</tspan></text>\n  <text x="385" y="202" font-size="11" fill="#15803d">"I suggest providing free healthcare for the elderly."</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="26" text-anchor="middle" font-size="15" font-weight="bold" fill="#0f172a">SUPPORTING DISADVANTAGED GROUPS: KEY CONCEPTS</text>\n  <rect x="25" y="48" width="205" height="190" rx="10" fill="#fef3c7" stroke="#d97706" stroke-width="2"/>\n  <text x="127" y="72" text-anchor="middle" font-size="12" font-weight="bold" fill="#92400e">1. Accessibility (Erişilebilirlik)</text>\n  <text x="38" y="98" font-size="11" fill="#78350f">• Wheelchair ramps &amp; elevators</text>\n  <text x="38" y="120" font-size="11" fill="#78350f">• Braille alphabet for the</text>\n  <text x="46" y="136" font-size="11" fill="#78350f">visually impaired</text>\n  <text x="38" y="158" font-size="11" fill="#78350f">• Sign language interpreters</text>\n  <text x="46" y="174" font-size="11" fill="#78350f">for the hearing impaired</text>\n  <text x="38" y="202" font-size="11" font-weight="bold" fill="#b45309">Goal: Barrier-free life</text>\n\n  <rect x="247" y="48" width="205" height="190" rx="10" fill="#ede9fe" stroke="#7c3aed" stroke-width="2"/>\n  <text x="349" y="72" text-anchor="middle" font-size="12" font-weight="bold" fill="#5b21b6">2. Social Inclusion (Kapsayıcılık)</text>\n  <text x="260" y="98" font-size="11" fill="#4c1d95">• Equal access to healthcare</text>\n  <text x="260" y="120" font-size="11" fill="#4c1d95">• Scholarships for low-income</text>\n  <text x="268" y="136" font-size="11" fill="#4c1d95">(underprivileged) students</text>\n  <text x="260" y="158" font-size="11" fill="#4c1d95">• Employment quotas for</text>\n  <text x="268" y="174" font-size="11" fill="#4c1d95">disabled citizens</text>\n  <text x="260" y="202" font-size="11" font-weight="bold" fill="#6d28d9">Goal: Equal opportunity</text>\n\n  <rect x="470" y="48" width="205" height="190" rx="10" fill="#fce7f3" stroke="#db2777" stroke-width="2"/>\n  <text x="572" y="72" text-anchor="middle" font-size="12" font-weight="bold" fill="#9d174d">3. Core Vocabulary</text>\n  <text x="483" y="98" font-size="11" fill="#831843">• <tspan font-weight="bold">Dignity:</tspan> Onur, haysiyet</text>\n  <text x="483" y="120" font-size="11" fill="#831843">• <tspan font-weight="bold">Prejudice:</tspan> Ön yargı</text>\n  <text x="483" y="142" font-size="11" fill="#831843">• <tspan font-weight="bold">Discrimination:</tspan> Ayrımcılık</text>\n  <text x="483" y="164" font-size="11" fill="#831843">• <tspan font-weight="bold">Deprivation:</tspan> Yoksunluk</text>\n  <text x="483" y="186" font-size="11" fill="#831843">• <tspan font-weight="bold">Solidarity:</tspan> Dayanışma</text>\n  <text x="483" y="208" font-size="11" font-weight="bold" fill="#be185d">Goal: Respect &amp; Justice</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="26" text-anchor="middle" font-size="15" font-weight="bold" fill="#0f172a">STRUCTURE OF AN ARGUMENTATIVE ESSAY (TARTIŞMACI MAKALE YAPISI)</text>\n  <rect x="20" y="48" width="150" height="130" rx="8" fill="#dbeafe" stroke="#2563eb" stroke-width="2"/>\n  <text x="95" y="70" text-anchor="middle" font-size="12" font-weight="bold" fill="#1e40af">1. Introduction</text>\n  <text x="95" y="92" text-anchor="middle" font-size="11" fill="#1e3a8a">• Hook (İlgi çekici giriş)</text>\n  <text x="95" y="112" text-anchor="middle" font-size="11" fill="#1e3a8a">• Background info</text>\n  <text x="95" y="132" text-anchor="middle" font-size="11" font-weight="bold" fill="#1d4ed8">• Thesis Statement</text>\n  <text x="95" y="150" text-anchor="middle" font-size="10" fill="#1e3a8a">(Ana sav cümlesi)</text>\n\n  <line x1="170" y1="113" x2="186" y2="113" stroke="#475569" stroke-width="2"/>\n  <polygon points="186,108 194,113 186,118" fill="#475569"/>\n\n  <rect x="194" y="48" width="150" height="130" rx="8" fill="#dcfce7" stroke="#16a34a" stroke-width="2"/>\n  <text x="269" y="70" text-anchor="middle" font-size="12" font-weight="bold" fill="#166534">2. Supporting Body</text>\n  <text x="269" y="92" text-anchor="middle" font-size="11" fill="#14532d">• Topic sentence</text>\n  <text x="269" y="112" text-anchor="middle" font-size="11" fill="#14532d">• Arguments &amp; facts</text>\n  <text x="269" y="132" text-anchor="middle" font-size="11" font-weight="bold" fill="#15803d">• Furthermore, Moreover,</text>\n  <text x="269" y="150" text-anchor="middle" font-size="10" fill="#14532d">In addition, For instance</text>\n\n  <line x1="344" y1="113" x2="360" y2="113" stroke="#475569" stroke-width="2"/>\n  <polygon points="360,108 368,113 360,118" fill="#475569"/>\n\n  <rect x="368" y="48" width="150" height="130" rx="8" fill="#fef3c7" stroke="#d97706" stroke-width="2"/>\n  <text x="443" y="70" text-anchor="middle" font-size="12" font-weight="bold" fill="#92400e">3. Counter &amp; Refute</text>\n  <text x="443" y="92" text-anchor="middle" font-size="11" fill="#78350f">• Opposing view</text>\n  <text x="443" y="112" text-anchor="middle" font-size="11" fill="#78350f">• Refutation (Çürütme)</text>\n  <text x="443" y="132" text-anchor="middle" font-size="11" font-weight="bold" fill="#b45309">• Critics argue that...</text>\n  <text x="443" y="150" text-anchor="middle" font-size="10" fill="#78350f">However, Nevertheless</text>\n\n  <line x1="518" y1="113" x2="534" y2="113" stroke="#475569" stroke-width="2"/>\n  <polygon points="534,108 542,113 534,118" fill="#475569"/>\n\n  <rect x="542" y="48" width="138" height="130" rx="8" fill="#fae8ff" stroke="#9333ea" stroke-width="2"/>\n  <text x="611" y="70" text-anchor="middle" font-size="12" font-weight="bold" fill="#6b21a8">4. Conclusion</text>\n  <text x="611" y="92" text-anchor="middle" font-size="11" fill="#581c87">• Restate thesis</text>\n  <text x="611" y="112" text-anchor="middle" font-size="11" fill="#581c87">• Final thought</text>\n  <text x="611" y="132" text-anchor="middle" font-size="11" font-weight="bold" fill="#6b21a8">• In conclusion,</text>\n  <text x="611" y="150" text-anchor="middle" font-size="10" fill="#581c87">To sum up, Therefore</text>\n\n  <rect x="20" y="192" width="660" height="52" rx="8" fill="#f1f5f9" stroke="#64748b" stroke-width="1.5"/>\n  <text x="350" y="213" text-anchor="middle" font-size="12" font-weight="bold" fill="#0f172a">KEY ELEMENT: COUNTER-ARGUMENT &amp; REFUTATION</text>\n  <text x="350" y="232" text-anchor="middle" font-size="11" fill="#334155">Tartışmacı makaleyi diğer makale türlerinden ayıran en önemli özellik, karşıt görüşe yer verip onu kanıtlarla çürütmesidir.</text>\n</svg>']

def uygula(v):
    for i, b in enumerate(v.get('bolumler', [])):
        if i < len(SVGS):
            b['gorsel'] = SVGS[i]
